/**
 * Corpus runner: audits every file in `corpus/` and writes a machine-readable
 * report to `docs/corpus-report.json`.
 *
 * The report is the project's regression baseline: it is regenerated by
 * `npm run corpus` and diffed in CI, so a change in DOMPurify's behaviour or
 * in purifytrace's reasoning shows up as a diff instead of a surprise.
 */
import { readFileSync, readdirSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import { JSDOM } from 'jsdom';
import { createAuditedSanitizer } from '../src/index.js';

const require = createRequire(import.meta.url);
const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..');

const factory = require('dompurify');
const createPurifier = factory.default || factory;
const window = new JSDOM('<!doctype html><html><body></body></html>').window;
const sanitizer = createAuditedSanitizer({ createDOMPurify: createPurifier, window });

const CONFIGS = {
  default: {},
  strict: {
    ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'p', 'br', 'ul', 'ol', 'li', 'a'],
    ALLOWED_ATTR: ['href', 'title'],
  },
  text: { ALLOWED_TAGS: [], ALLOWED_ATTR: [], KEEP_CONTENT: true },
  noDataAttrs: { ALLOW_DATA_ATTR: false },
};

const corpusDir = join(root, 'corpus');
const files = readdirSync(corpusDir)
  .filter((name) => /\.(html?|svg|txt)$/i.test(name))
  .sort();

const report = {
  generatedBy: 'npm run corpus',
  dompurify: sanitizer.dompurify,
  purifytrace: sanitizer.version,
  configs: {},
};

for (const [name, config] of Object.entries(CONFIGS)) {
  const entries = [];
  for (const file of files) {
    const input = readFileSync(join(corpusDir, file), 'utf8');
    const { output, trail } = sanitizer.audit(input, config);
    entries.push({
      file,
      output,
      events: trail.events.map((event) => ({
        action: event.action,
        target: event.target,
        on: event.on,
        path: event.path,
        reason: event.reason.code,
        policyKey: event.reason.policyKey,
        confidence: event.reason.confidence,
      })),
      findings: trail.findings.map((finding) => ({ code: finding.code, severity: finding.severity })),
      upstreamRecords: trail.bookkeeping.upstreamRecords,
      upstreamMismatch:
        trail.bookkeeping.auditOnly.length +
        trail.bookkeeping.upstreamOnly.filter((item) => !item.explained).length +
        trail.bookkeeping.auditOnlyAttributes.length +
        trail.bookkeeping.upstreamOnlyAttributes.length,
      prewalkLosses:
        trail.prewalk.headIgnored.length + trail.prewalk.bodyUnseen.length + (trail.prewalk.textChanged ? 1 : 0),
    });
  }
  report.configs[name] = {
    files: entries.length,
    events: entries.reduce((sum, entry) => sum + entry.events.length, 0),
    findings: entries.reduce((sum, entry) => sum + entry.findings.length, 0),
    highFindings: entries.reduce(
      (sum, entry) => sum + entry.findings.filter((finding) => finding.severity === 'high').length,
      0
    ),
    upstreamMismatch: entries.reduce((sum, entry) => sum + entry.upstreamMismatch, 0),
    prewalkLosses: entries.reduce((sum, entry) => sum + entry.prewalkLosses, 0),
    entries,
  };
}

mkdirSync(join(root, 'docs'), { recursive: true });
writeFileSync(join(root, 'docs', 'corpus-report.json'), `${JSON.stringify(report, null, 2)}\n`, 'utf8');

console.log(`corpus report written: docs/corpus-report.json`);
for (const [name, stats] of Object.entries(report.configs)) {
  console.log(
    `  ${name.padEnd(12)} files ${stats.files} · events ${stats.events} · findings ${stats.findings} ` +
      `(high ${stats.highFindings}) · upstream mismatch ${stats.upstreamMismatch} · pre-walk ${stats.prewalkLosses}`
  );
}
